import os,json,urllib.request,urllib.error,sys,pathlib
root=pathlib.Path(__file__).parent

def call(method,path,body=None,label=None):
 req=urllib.request.Request(os.environ['MCPJAM_API_URL'].rstrip('/')+path,data=json.dumps(body).encode() if body is not None else None,headers={'Authorization':'Bearer '+os.environ['MCPJAM_API_KEY'],'Content-Type':'application/json'},method=method)
 try:
  with urllib.request.urlopen(req,timeout=20) as r: status=r.status; raw=r.read().decode()
 except urllib.error.HTTPError as e: status=e.code; raw=e.read().decode()
 try: data=json.loads(raw)
 except ValueError:data=raw
 result={'status':status,'body':data}
 if label:(root/(label+'.json')).write_text(json.dumps(result,indent=2))
 return result
if __name__=='__main__':
 print(json.dumps(call(sys.argv[1],sys.argv[2],json.loads(pathlib.Path(sys.argv[3]).read_text()) if len(sys.argv)>3 else None,sys.argv[4] if len(sys.argv)>4 else None),indent=2))
